//! 🔺️ delete-texture leaf-owned typed sparse operation diff.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfTexture;
use crate::artifacts::gltf::schema::diff::GltfDiff;
use crate::artifacts::gltf::schema::mutations::delete_texture::mutation::{apply, validate, GltfDeleteTexturePayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{textures_op, family_diff, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.delete-texture.v1";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfDeleteTextureOperation { Insert { position: usize, item: GltfTexture }, Delete { index: usize, removed: GltfTexture }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfDeleteTextureDiff { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfDeleteTexturePayload, pub operation: GltfDeleteTextureOperation }
async fn operation(payload: &GltfDeleteTexturePayload, base: &GltfSnapshot) -> GltfDeleteTextureOperation { GltfDeleteTextureOperation::Delete { index: payload.index, removed: base.document.textures[payload.index].clone() } }
async fn touched_paths(payload: &GltfDeleteTexturePayload) -> Vec<String> { vec![format!("document/textures/{}", payload.index)] }
pub async fn validate_diff(diff: &GltfDeleteTextureDiff, base: &GltfSnapshot) -> Result<(), GltfTopLevelMutationRejection> { if diff.id != ID || diff.version != 1 { return Err(reject("gltf.mutation.invalid-diff-envelope", "diff", "descriptor identity does not match")); } if diff.touched_paths != touched_paths(&diff.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "diff/touchedPaths", "paths must be concrete payload-derived locations")); } validate(&diff.payload, base)?; if diff.operation != operation(&diff.payload, base) { return Err(reject("gltf.mutation.invalid-sparse-operation", "diff/operation", "operation must equal the direct typed delta")); } Ok(()) }
pub async fn apply_diff(diff: &GltfDeleteTextureDiff, base: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_diff(diff, base)?; let mut next = base.clone(); let operation = &diff.operation; match operation { GltfDeleteTextureOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Textures, &Change::Insert(*position))?; next.document.textures.insert(*position, item.clone());  }, GltfDeleteTextureOperation::Delete { index, .. } => { textures_op(&mut next, GltfTopLevelFamily::Textures, *index, None, None)?;  }, GltfDeleteTextureOperation::Move { index, position } => { textures_op(&mut next, GltfTopLevelFamily::Textures, *index, Some(*position), None)?;  }, GltfDeleteTextureOperation::Reorder { order } => { textures_op(&mut next, GltfTopLevelFamily::Textures, order[0], None, Some(order))?;  } } Ok(next) }
pub async fn encode(diff: &GltfDeleteTextureDiff) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(diff).map_err(|error| reject("gltf.mutation.encode-failed", "diff", error.to_string())) }
pub async fn derive(payload: &GltfDeleteTexturePayload, base: &GltfSnapshot) -> Result<GltfDeleteTextureDiff, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfDeleteTextureDiff { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
pub async fn derive_transitional_gltf_diff(payload: &GltfDeleteTexturePayload, base: &GltfSnapshot) -> Result<GltfDiff, GltfTopLevelMutationRejection> { let next = apply(payload, base)?; Ok(family_diff(GltfTopLevelFamily::Textures, base, &next)) }
